.help-icon { display: inline-grid; place-items: center; width: 1.2em; height: 1.2em; border-radius: 50%; background: #e5e7eb; font-size: 0.8em; cursor: help; }
.label-row { display: flex; align-items: center; gap: 0.4rem; margin-top: 0.75rem; }
.label-row label { margin-top: 0; }
.help-icon { position: relative; }
.help-icon:focus-visible { outline: 2px solid #1d4ed8; outline-offset: 2px; }

/* Tooltip: above the icon by default, below when .tooltip-below is set (see app.js). */
.tooltip {
  position: absolute; left: 50%; bottom: calc(100% + 8px);
  transform: translateX(-50%);
  width: max-content; max-width: 16rem;
  padding: 0.4rem 0.6rem; border-radius: 4px;
  background: #1d1f23; color: white;
  font-size: 0.85rem; font-weight: 400; line-height: 1.3; cursor: default;
  visibility: hidden; opacity: 0; transition: opacity 0.15s;
  z-index: 10;
}
.tooltip::after { /* arrow */
  content: ""; position: absolute; left: 50%; top: 100%;
  transform: translateX(-50%);
  border: 5px solid transparent; border-top-color: #1d1f23;
}
.help-icon.tooltip-below .tooltip { bottom: auto; top: calc(100% + 8px); }
.help-icon.tooltip-below .tooltip::after { top: auto; bottom: 100%; border-top-color: transparent; border-bottom-color: #1d1f23; }

.help-icon:is(:hover, :focus-visible):not(.tooltip-dismissed) .tooltip { visibility: visible; opacity: 1; }

@media (prefers-reduced-motion: reduce) { .tooltip { transition: none; } }

